"""Inspect the workspace: list files and summarize any SQLite databases (read-only)."""
import sqlite3
from pathlib import Path


def main() -> None:
    root = Path.cwd()
    print(f"Workspace: {root}")
    print("\nFiles in workspace:")
    for entry in sorted(root.iterdir()):
        marker = "<DIR>" if entry.is_dir() else f"{entry.stat().st_size} bytes"
        print(f"  {entry.name}  ({marker})")

    print("\nSQLite databases found:")
    found = False
    for entry in sorted(root.iterdir()):
        if entry.is_file() and entry.suffix.lower() in (".db", ".sqlite", ".sqlite3"):
            found = True
            print(f"\n--- {entry.name} ---")
            try:
                with sqlite3.connect(entry) as conn:
                    conn.row_factory = sqlite3.Row
                    cur = conn.cursor()
                    cur.execute(
                        "SELECT name, type FROM sqlite_master "
                        "WHERE type IN ('table', 'view') ORDER BY name"
                    )
                    objects = cur.fetchall()
                    if not objects:
                        print("  (no tables or views)")
                    for obj in objects:
                        print(f"  {obj['type']}: {obj['name']}")
                        cur.execute(
                            "SELECT sql FROM sqlite_master WHERE name = ?",
                            (obj["name"],),
                        )
                        row = cur.fetchone()
                        if row and row["sql"]:
                            print(f"    SQL: {row['sql']}")
            except sqlite3.DatabaseError as exc:
                print(f"  could not open as SQLite: {exc}")
    if not found:
        print("  (none)")


if __name__ == "__main__":
    main()

